<?php

declare(strict_types=1);

namespace App\Models;

use App\Enums\PayoutStatus;
use App\Support\Ids\HasPrefixedId;
use App\Support\Money\Money;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Support\Carbon;

/* @properties-start (generated by dev:model-docs) */
/**
 * @property string $id
 * @property string $reference
 * @property string $user_id
 * @property string $wallet_id
 * @property string $payout_method_id
 * @property string|null $batch_id
 * @property int $amount
 * @property string $currency
 * @property int $fee_amount
 * @property int $net_amount
 * @property string $destination_currency
 * @property int $destination_amount
 * @property float $exchange_rate
 * @property PayoutStatus $status
 * @property bool $requires_approval
 * @property string|null $approval_reason
 * @property bool $flagged
 * @property string|null $hold_reason
 * @property string|null $rejection_reason
 * @property string|null $provider
 * @property string|null $provider_reference
 * @property string|null $failure_reason
 * @property string|null $approved_by
 * @property Carbon|null $approved_at
 * @property Carbon|null $paid_at
 * @property Carbon|null $created_at
 * @property Carbon|null $updated_at
 */
/* @properties-end */
class Payout extends Model
{
    use HasPrefixedId;

    protected static string $idPrefix = 'po';

    protected $fillable = [
        'reference', 'user_id', 'wallet_id', 'payout_method_id', 'batch_id', 'amount', 'currency', 'fee_amount',
        'net_amount', 'destination_currency', 'destination_amount', 'exchange_rate', 'status', 'requires_approval',
        'approval_reason', 'flagged', 'hold_reason', 'rejection_reason', 'provider', 'provider_reference',
        'failure_reason', 'approved_by', 'approved_at', 'paid_at',
    ];

    protected function casts(): array
    {
        return [
            'status' => PayoutStatus::class,
            'amount' => 'integer',
            'fee_amount' => 'integer',
            'net_amount' => 'integer',
            'destination_amount' => 'integer',
            'exchange_rate' => 'float',
            'requires_approval' => 'boolean',
            'flagged' => 'boolean',
            'approved_at' => 'datetime',
            'paid_at' => 'datetime',
        ];
    }

    /** @return BelongsTo<User, $this> */
    public function user(): BelongsTo
    {
        return $this->belongsTo(User::class);
    }

    /** @return BelongsTo<Wallet, $this> */
    public function wallet(): BelongsTo
    {
        return $this->belongsTo(Wallet::class);
    }

    /** @return BelongsTo<PayoutMethod, $this> */
    public function payoutMethod(): BelongsTo
    {
        return $this->belongsTo(PayoutMethod::class)->withTrashed();
    }

    /** @return BelongsTo<PayoutBatch, $this> */
    public function batch(): BelongsTo
    {
        return $this->belongsTo(PayoutBatch::class, 'batch_id');
    }

    public function money(): Money
    {
        return Money::of($this->amount, $this->currency);
    }
}
